  useEffect(() => { document.documentElement.setAttribute('data-theme', theme); }, []);
  useEffect(() => {
    if (learnerMode && !currentPage.startsWith('learner-')) {
      setCurrentPage('learner-explore');
    }
  }, [learnerMode]);
  useEffect(() => {
    if (!isNewUser || dashboardLoading) return;
    const t = setInterval(() => setHeroSlide(s => (s + 1) % 3), 5000);
    return () => clearInterval(t);
  }, [isNewUser, dashboardLoading]);
  useEffect(() => {
    if (!onboardingModalOpen) { setOnboardingRect(null); setTourFading(false); setTourTooltipVisible(false); return; }
    const ref = onboardingRefs[onboardingStep];
    const isFirstStep = !onboardingRect;
    const timers = [];
    const t = (fn, ms) => { const id = setTimeout(fn, ms); timers.push(id); };

    if (isFirstStep) {
      // First step: fade in smoothly
      t(() => {
        const r2 = ref && ref.current ? ref.current.getBoundingClientRect() : null;
        if (r2) setOnboardingRect({ top: r2.top, left: r2.left, width: r2.width, height: r2.height, viewTop: r2.top, viewBottom: r2.bottom, step: onboardingStep });
        setTourFading(false);
        t(() => { setTourTooltipVisible(true); }, 150);
      }, 100);
    } else {
      // Phase 1: Fade out tooltip + highlight together
      tourTransitioning.current = true;
      setTourTooltipVisible(false);
      setTourFading(true);
      // Phase 2: After fade out, scroll to new element
      // Only skip scroll for step 2→3 on desktop (side by side); on mobile they stack
      const isMobileLayout = window.innerWidth < 1024;
      const skipScroll = !isMobileLayout && onboardingStep === 2 && prevOnboardingStep.current === 1;
      t(() => {
        setOnboardingRect(null);
        const sc = scrollContainerRef.current;
        prevOnboardingStep.current = onboardingStep;
        if (ref && ref.current && !skipScroll) {
          if (isMobileLayout) {
            // Mobile: scroll card into view, then adjust so top portion is visible above the bottom tooltip
            ref.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
          } else if (onboardingStep === 3) {
            const targetTop = 280;
            const currentTop = ref.current.getBoundingClientRect().top;
            if (sc) sc.scrollBy({ top: currentTop - targetTop, behavior: 'smooth' });
          } else if (onboardingStep === 1 || onboardingStep === 2) {
            const targetTop = 120;
            const currentTop = ref.current.getBoundingClientRect().top;
            if (sc) sc.scrollBy({ top: currentTop - targetTop, behavior: 'smooth' });
          } else {
            ref.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
            t(() => { if (sc) sc.scrollBy({ top: -80, behavior: 'smooth' }); }, 300);
          }
        }
        // Phase 3: After scroll settles, fade in highlight
        const scrollSettleTime = skipScroll ? 50 : (onboardingStep === 3 ? 800 : ((onboardingStep === 1 || onboardingStep === 2) ? 700 : 500));
        t(() => {
          const r2 = ref && ref.current ? ref.current.getBoundingClientRect() : null;
          if (r2) setOnboardingRect({ top: r2.top, left: r2.left, width: r2.width, height: r2.height, viewTop: r2.top, viewBottom: r2.bottom, step: onboardingStep });
          setTourFading(false);
          // Phase 4: After highlight settles, fade in tooltip
          t(() => { setTourTooltipVisible(true); tourTransitioning.current = false; }, 200);
        }, scrollSettleTime);
      }, 200);
    }

    prevOnboardingStep.current = onboardingStep;
    const scEl = scrollContainerRef.current;
    const updateRect = () => {
      if (tourTransitioning.current) return;
      const r2 = ref && ref.current ? ref.current.getBoundingClientRect() : null;
      if (r2) setOnboardingRect({ top: r2.top, left: r2.left, width: r2.width, height: r2.height, viewTop: r2.top, viewBottom: r2.bottom, step: onboardingStep });
    };
    window.addEventListener('resize', updateRect);
    if (scEl) scEl.addEventListener('scroll', updateRect);
    return () => { timers.forEach(clearTimeout); window.removeEventListener('resize', updateRect); if (scEl) scEl.removeEventListener('scroll', updateRect); };
  }, [onboardingModalOpen, onboardingStep]);
  const [loggingOut, setLoggingOut] = useState(false);
