  const handleLogin = (newUser = false) => {
    if (window.innerWidth < 1024) {
      setLoginStage(5);
      setTimeout(() => {
        setIsNewUser(newUser);
        setIsLoggedIn(true);
        setLoggingIn(true);
        setLoginStage(0);
        setTimeout(() => { setLoggingIn(false); }, 800);
      }, 2800);
      return;
    }
    setLoginStage(1); // fade form
    setTimeout(() => {
      setLoginStage(3); // stretch canvas to fullscreen
      setTimeout(() => {
        setLoginStage(4); // fullscreen canvas + loader (orbs keep animating)
        setTimeout(() => {
          setIsNewUser(newUser);
          setIsLoggedIn(true);
          setLoggingIn(true);
          setLoginStage(0);
          setTimeout(() => { setLoggingIn(false); }, 800);
        }, 2800);
      }, 400);
    }, 500);
  };
