  useEffect(() => {
    if (isLoggedIn || loggingOut) {
      if (animFrameRef.current) { cancelAnimationFrame(animFrameRef.current); animFrameRef.current = null; }
      return;
    }
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const resize = () => { canvas.width = canvas.offsetWidth * dpr; canvas.height = canvas.offsetHeight * dpr; };
    resize();
    window.addEventListener('resize', resize);
    let t = 0;
    // Slow-drifting soft gradient orbs
    const orbs = Array.from({ length: 6 }, (_, i) => ({
      x: 0.2 + Math.random() * 0.6, y: 0.2 + Math.random() * 0.6,
      r: 0.3 + Math.random() * 0.25,
      phase: i * Math.PI * 0.5,
      drift: 0.08 + Math.random() * 0.1,
    }));
    const draw = () => {
      t += 0.010;
      const w = canvas.width, h = canvas.height;
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, w, h);
      // Render soft orbs
      orbs.forEach(orb => {
        const cx = (orb.x + Math.sin(t + orb.phase) * orb.drift) * w;
        const cy = (orb.y + Math.cos(t * 0.7 + orb.phase) * orb.drift) * h;
        const radius = orb.r * Math.min(w, h);
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
        const b = 10 + Math.sin(t * 1.5 + orb.phase) * 3;
        grad.addColorStop(0, `rgba(${b * 2.8}, ${b * 2.8}, ${b * 3.08}, 1)`);
        grad.addColorStop(0.4, `rgba(${b * 1.4}, ${b * 1.4}, ${b * 1.54}, 0.9)`);
        grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, w, h);
      });
      // Faint horizontal light streaks
      for (let i = 0; i < 3; i++) {
        const y = (0.25 + i * 0.25 + Math.sin(t * 0.5 + i * 2) * 0.03) * h;
        const grad = ctx.createLinearGradient(0, y - 40 * dpr, 0, y + 40 * dpr);
        grad.addColorStop(0, 'rgba(255,255,255,0)');
        grad.addColorStop(0.5, `rgba(255,255,255,${0.017 + Math.sin(t + i) * 0.007})`);
        grad.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = grad;
        ctx.fillRect(0, y - 40 * dpr, w, 80 * dpr);
      }
      animFrameRef.current = requestAnimationFrame(draw);
    };
    draw();
    return () => { window.removeEventListener('resize', resize); if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current); };
  }, [isLoggedIn, loggingOut, loginStage]);

