  const genericSort = (data, sortCol, sortDir, colMap) => {
    if (!sortCol || !colMap[sortCol]) return data;
    const getter = colMap[sortCol];
    return [...data].sort((a, b) => {
      const va = getter(a), vb = getter(b);
      const cmp = typeof va === 'string' ? va.localeCompare(vb) : va - vb;
      return sortDir === 'asc' ? cmp : -cmp;
    });
  };

  const filteredUsers = usersData.filter(u => {
    if (userSearch && !u.name.toLowerCase().includes(userSearch.toLowerCase()) && !u.email.toLowerCase().includes(userSearch.toLowerCase())) return false;
    if (roleFilter && u.role !== roleFilter) return false;
    if (statusFilter && u.status !== statusFilter) return false;
    return true;
  });
  const sortedUsers = genericSort(filteredUsers, usersSortCol, usersSortDir, {
    name: u => u.name, email: u => u.email, role: u => u.role, status: u => u.status, lastActive: u => u.lastActive,
  });

