                                const allOnPage = paginatedGroupDetailUsers.map((_, i) => i);
                                const allSelected = allOnPage.every(i => selectedGroupDetailUsers.includes(i));
                                setSelectedGroupDetailUsers(allSelected ? [] : allOnPage);
