                        const attrs = [
                          { name: 'Department', value: ['Engineering', 'Marketing', 'Sales', 'Support'][selectedUserIndex % 4] },
                          { name: 'Employee ID', value: `EMP-${1000 + selectedUserIndex}` },
                          { name: 'Location', value: ['San Francisco', 'New York', 'London', 'Berlin'][selectedUserIndex % 4] },
                          { name: 'Hire Date', value: '2024-03-15' },
                          { name: 'Job Title', value: user.role === 'Super Admin' ? 'Platform Owner' : user.role === 'Admin' ? 'Platform Administrator' : 'Team Member' },
                        ];
                        const visibleAttrs = attrs.slice(0, 3 + (selectedUserIndex % 4));
