                            <div className="flex items-center gap-2">
                              <div className="w-2 h-2 rounded-full" style={{ backgroundColor: profileStatus === 'Active' ? 'var(--status-active)' : 'var(--inactive-dot)' }}></div>
                              <span className="text-sm font-medium" style={{ color: profileStatus === 'Active' ? 'var(--icon-green-text)' : 'var(--text-muted)' }}>{profileStatus}</span>
                            </div>
                            <button
